// PreToolUse hook (Edit|Write): blocks edits that break repo rules.
// - src/bindings/ is generated by ts-rs (`cargo test`); never edit it by hand.
// - Migrations already merged into `main` are append-only.
// Exit code 2 blocks the tool call and shows stderr to Claude.
import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import path from "node:path";

const input = JSON.parse(readFileSync(0, "utf8"));
const filePath = input.tool_input?.file_path;
const projectDir = process.env.CLAUDE_PROJECT_DIR ?? input.cwd;
if (!filePath || !projectDir) process.exit(0);

const rel = path.relative(projectDir, path.resolve(projectDir, filePath)).split(path.sep).join("/");

if (rel.startsWith("src/bindings/")) {
  console.error(
    "src/bindings/ is generated by ts-rs. Change the Rust type and run `cargo test` instead.",
  );
  process.exit(2);
}

if (/^src-tauri\/migrations\/[^/]+\.sql$/.test(rel)) {
  let merged = false;
  try {
    execFileSync("git", ["-C", projectDir, "cat-file", "-e", `main:${rel}`], { stdio: "ignore" });
    merged = true;
  } catch {
    // Not on main yet (new or unmerged migration): editing is allowed.
  }
  if (merged) {
    console.error(
      `${rel} is already merged into main; migrations are append-only. ` +
        "Add the next numbered file in src-tauri/migrations/ and append it to MIGRATIONS in db.rs.",
    );
    process.exit(2);
  }
}

process.exit(0);
